  preveri('prevodi ro: mnozine one/few/other', slabeRo.length === 0, slabeRo.slice(0, 5).map(([k]) => k).join(', '))
  const crticeRo = listi(ro).filter(([, v]) => (typeof v === 'string' ? [v] : Object.values(v)).some((b) => /[—–]/.test(b)))
