  const tekma = await poskusi(new Response(`<html><div class="detail">${beri('jp-jfl-tekma-2026A0010111-cas-kartoni.html').slice(20)}<div class="section"><h3>監　督</h3>X</div><div class="section"><h3>試合情報</h3>Y</div>`, { status: 200 }))
